#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/video.h>
#include <zephyr/drivers/video/video_emul.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(video_emul_rx, CONFIG_VIDEO_LOG_LEVEL);

struct emul_rx_config {
	struct video_emul_imager_api *imager_api;
	const struct device *imager;
};

struct emul_rx_data {
	struct video_format fmt;
	struct k_fifo buf_fifo;
	struct k_work_delayable work;
	video_callback_t cb;
	void *user_data;
	uint32_t timeout;
	enum video_stream_state state;
	struct k_sem sem;
};

static void emul_rx_worker(struct k_work *work)
{
	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct emul_rx_data *data = CONTAINER_OF(dwork, struct emul_rx_data, work);
	const struct device *dev = CONTAINER_OF(data, const struct device, data);
	const struct emul_rx_config *cfg = dev->config;
	struct video_buffer *vbuf;
	size_t frame_size;

	if (data->state != VIDEO_STREAM_STATE_STREAMING) {
		return;
	}

	frame_size = data->fmt.pitch * data->fmt.height;

	LOG_DBG("Queueing a frame of %zu bytes in format %c%c%c%c %ux%u", frame_size,
		(char)data->fmt.pixelformat, (char)(data->fmt.pixelformat >> 8),
		(char)(data->fmt.pixelformat >> 16), (char)(data->fmt.pixelformat >> 24),
		data->fmt.width, data->fmt.height);

	vbuf = k_fifo_get(&data->buf_fifo, K_NO_WAIT);
	if (vbuf == NULL) {
		LOG_WRN("No buffer available, frame dropped");
		goto resched;
	}

	LOG_DBG("Inserting %zu bytes into buffer %p", frame_size, vbuf->buffer);

	cfg->imager_api->get_frame(cfg->imager, vbuf->buffer, frame_size);
	vbuf->bytesused = frame_size;
	vbuf->timestamp = k_uptime_get_32();

	if (data->cb) {
		data->cb(dev, VIDEO_BUF_DONE, vbuf, data->user_data);
	}

resched:
	k_work_reschedule(&data->work, K_MSEC(data->timeout));
}

static int emul_rx_set_callback(const struct device *dev, video_callback_t cb, void *user_data)
{
	struct emul_rx_data *data = dev->data;

	data->cb = cb;
	data->user_data = user_data;

	return 0;
}

static int emul_rx_set_format(const struct device *dev, struct video_format *fmt)
{
	struct emul_rx_data *data = dev->data;
	const struct emul_rx_config *cfg = dev->config;
	struct video_emul_imager_mode mode;

	mode.format.pixelformat = fmt->pixelformat;
	mode.format.width = fmt->width;
	mode.format.height = fmt->height;
	mode.format.pitch = fmt->pitch;

	cfg->imager_api->set_mode(cfg->imager, &mode);

	data->fmt = *fmt;

	return 0;
}

static int emul_rx_get_format(const struct device *dev, struct video_format *fmt)
{
	struct emul_rx_data *data = dev->data;

	*fmt = data->fmt;

	return 0;
}

static int emul_rx_stream_start(const struct device *dev)
{
	struct emul_rx_data *data = dev->data;

	data->state = VIDEO_STREAM_STATE_STREAMING;
	k_work_reschedule(&data->work, K_NO_WAIT);

	return 0;
}

static int emul_rx_stream_stop(const struct device *dev)
{
	struct emul_rx_data *data = dev->data;

	data->state = VIDEO_STREAM_STATE_STOPPED;
	k_work_cancel_delayable(&data->work);

	return 0;
}

static int emul_rx_flush(const struct device *dev, bool cancel)
{
	struct emul_rx_data *data = dev->data;
	struct video_buffer *vbuf;

	if (data->state != VIDEO_STREAM_STATE_STREAMING) {
		return -EPIPE;
	}

	while ((vbuf = k_fifo_get(&data->buf_fifo, K_NO_WAIT)) != NULL) {
		if (data->cb) {
			data->cb(dev, cancel ? VIDEO_BUF_CANCELED : VIDEO_BUF_DONE, vbuf,
				 data->user_data);
		}
	}

	return 0;
}

static int emul_rx_enqueue(const struct device *dev, struct video_buffer *vbuf)
{
	struct emul_rx_data *data = dev->data;
	size_t frame_size;

	frame_size = data->fmt.pitch * data->fmt.height;
	if (vbuf->size < frame_size) {
		return -ENOMEM;
	}

	k_fifo_put(&data->buf_fifo, vbuf);

	return 0;
}

static int emul_rx_dequeue(const struct device *dev, struct video_buffer **vbuf,
			   k_timeout_t timeout)
{
	return -ENOSYS;
}

static int emul_rx_get_caps(const struct device *dev, struct video_caps *caps)
{
	const struct emul_rx_config *cfg = dev->config;

	return cfg->imager_api->get_caps(cfg->imager, caps);
}

static int emul_rx_get_frame_interval(const struct device *dev, struct video_frmival *frmival)
{
	const struct emul_rx_config *cfg = dev->config;
	struct video_emul_imager_mode mode;
	int ret;

	ret = cfg->imager_api->get_mode(cfg->imager, &mode);
	if (ret) {
		return ret;
	}

	*frmival = mode.frmival;

	return 0;
}

static int emul_rx_set_frame_interval(const struct device *dev, struct video_frmival *frmival)
{
	struct emul_rx_data *data = dev->data;
	const struct emul_rx_config *cfg = dev->config;
	struct video_emul_imager_mode mode;
	int ret;

	ret = cfg->imager_api->get_mode(cfg->imager, &mode);
	if (ret) {
		return ret;
	}

	mode.frmival = *frmival;

	ret = cfg->imager_api->set_mode(cfg->imager, &mode);
	if (ret) {
		return ret;
	}

	data->timeout = frmival->numerator * 1000 / frmival->denominator;

	return 0;
}

static const struct video_driver_api emul_rx_api = {
	.set_callback = emul_rx_set_callback,
	.set_format = emul_rx_set_format,
	.get_format = emul_rx_get_format,
	.stream_start = emul_rx_stream_start,
	.stream_stop = emul_rx_stream_stop,
	.flush = emul_rx_flush,
	.enqueue = emul_rx_enqueue,
	.dequeue = emul_rx_dequeue,
	.get_caps = emul_rx_get_caps,
	.get_frmival = emul_rx_get_frame_interval,
	.set_frmival = emul_rx_set_frame_interval,
};

static int emul_rx_init(const struct device *dev)
{
	struct emul_rx_data *data = dev->data;

	k_fifo_init(&data->buf_fifo);
	k_work_init_delayable(&data->work, emul_rx_worker);
	k_sem_init(&data->sem, 1, 1);

	return 0;
}

#define EMUL_RX_INIT(n)                                                                            \
	static const struct emul_rx_config emul_rx_config_##n = {                                  \
		.imager = DEVICE_DT_GET(DT_INST_PHANDLE(n, imager)),                                \
		.imager_api = (struct video_emul_imager_api *)DEVICE_DT_GET(DT_INST_PHANDLE(n,      \
									 imager))   \
				  ->api,                                                           \
	};                                                                                         \
	                                                                                           \
	static struct emul_rx_data emul_rx_data_##n;                                               \
	                                                                                           \
	DEVICE_DT_INST_DEFINE(n, &emul_rx_init, NULL, &emul_rx_data_##n, &emul_rx_config_##n,       \
			      POST_KERNEL, CONFIG_VIDEO_INIT_PRIORITY, &emul_rx_api);

DT_INST_FOREACH_STATUS_OKAY(EMUL_RX_INIT)
